def symbol(name, body):
    return f'  <symbol id="i-{name}" viewBox="0 0 24 24"><g {S}>{body}</g></symbol>'

root = pathlib.Path(__file__).resolve().parent.parent
f = root / 'index.html'
html = f.read_text(encoding='utf-8')
for name, body in ICONS.items():
    new = symbol(name, body)
    pat = re.compile(r'  <symbol id="i-' + re.escape(name) + r'"[^\n]*</symbol>')
    if pat.search(html):
        html = pat.sub(lambda m: new, html, count=1)
    else:
        html = html.replace('  <symbol id="i-logo"', new + '\n  <symbol id="i-logo"', 1)
f.write_text(html, encoding='utf-8', newline='')
print('icons:', len(ICONS))
